// src/components/Gamification.js
import React, { useState, useEffect } from 'react';

const Gamification = ({ user, language }) => {
  const [badges, setBadges] = useState([]);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    // Simulate badge data
    const userBadges = [
      { id: 1, name: 'New Voter', earned: true, color: '#FF6B6B', shape: 'circle' },
      { id: 2, name: 'Eligibility Checked', earned: true, color: '#4ECDC4', shape: 'star' },
      { id: 3, name: 'Voter Educator', earned: false, color: '#45B7D1', shape: 'hexagon' },
      { id: 4, name: 'Community Leader', earned: false, color: '#FFA07A', shape: 'square' },
      { id: 5, name: 'Registration Champion', earned: false, color: '#98D8C8', shape: 'diamond' },
      { id: 6, name: 'Informed Citizen', earned: false, color: '#F7DC6F', shape: 'circle' }
    ];
    
    setBadges(userBadges);
    setProgress(33); // 2 out of 6 badges earned
  }, []);

  const translations = {
    hindi: {
      title: "आपकी उपलब्धियां",
      progress: "प्रगति",
      badgesEarned: "बैज अर्जित किए",
      of: "में से",
      badges: {
        newVoter: "नया मतदाता",
        eligibilityChecked: "पात्रता जांच पूरी",
        voterEducator: "मतदाता शिक्षक",
        communityLeader: "समुदाय नेता",
        registrationChampion: "पंजीकरण चैंपियन",
        informedCitizen: "सूचित नागरिक"
      }
    },
    english: {
      title: "Your Achievements",
      progress: "Progress",
      badgesEarned: "Badges Earned",
      of: "of",
      badges: {
        newVoter: "New Voter",
        eligibilityChecked: "Eligibility Checked",
        voterEducator: "Voter Educator",
        communityLeader: "Community Leader",
        registrationChampion: "Registration Champion",
        informedCitizen: "Informed Citizen"
      }
    }
  };

  const t = translations[language];

  const getBadgeName = (badgeName) => {
    return t.badges[badgeName.replace(/\s+/g, '').toLowerCase()] || badgeName;
  };

  return (
    <div className="gamification">
      <h2>{t.title}</h2>
      
      <div className="progress-section">
        <h3>{t.progress}</h3>
        <div className="progress-bar">
          <div 
            className="progress-fill" 
            style={{ width: `${progress}%` }}
          ></div>
        </div>
        <p>{badges.filter(b => b.earned).length} {t.of} {badges.length} {t.badgesEarned}</p>
      </div>

      <div className="badges-grid">
        {badges.map(badge => (
          <div 
            key={badge.id} 
            className={`badge ${badge.earned ? 'earned' : 'locked'}`}
            style={{ 
              backgroundColor: badge.earned ? badge.color : '#CCCCCC',
              borderRadius: badge.shape === 'circle' ? '50%' : 
                           badge.shape === 'square' ? '0' : 
                           badge.shape === 'star' ? '50% 50% 0 0' : '10px'
            }}
          >
            <div className="badge-icon">
              {badge.earned ? '✓' : '🔒'}
            </div>
            <div className="badge-name">
              {getBadgeName(badge.name)}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Gamification;
